// Offline support.
//
// The whole point of a pocket guide is being abroad without data, so the app has
// to work with the network off -- including export, which is why every renderer is
// client-side. The shell is precached on install; a language's corpus and fonts
// are two megabytes or so per script, far too much to cache speculatively, so they
// are fetched when opened or explicitly saved from Settings.
//
// Scoped to /pocket-language-guide/, so nothing else on the site is affected.

// The precache list and VERSION are generated by scripts/build_shell.mjs from what
// is actually on disk (`npm run shell`). It used to be a hand-written array here,
// and it drifted: seven modules were missing, so the studio would have failed with
// the network off. VERSION is a content hash of those files, so a deploy re-primes
// the cache without anyone remembering to bump anything.
const VERSION = 'plg-484ccf81f5be';
const SHELL_CACHE = `${VERSION}-shell`;
/**
 * **Not version-scoped, deliberately.** The shell has to be replaced wholesale on a
 * deploy or a reader gets last week's modules against this week's data. A saved
 * language pack is the opposite: it is the corpus rows and the subset fonts for one
 * pair, it is megabytes, and someone pressed a button to get it -- usually before
 * going somewhere without a network, which is the whole reason the button exists.
 * Scoping this to `VERSION` meant a one-character CSS change silently discarded
 * every pack every reader had saved, because `VERSION` is a content hash of the
 * *shell*.
 *
 * Content hashes in the shell's offline manifest refresh changed cached files on
 * upgrade. A failed refresh keeps its old bytes and old hash, so it works offline
 * and can be retried when the file is next opened with a connection.
 */
const PACK_CACHE = 'plg-packs';
/** The prefix every cache of ours carries, which is what tells them apart from every
 * other app's on this origin. `VERSION` already begins with it. */
const OURS = 'plg-';
const SHELL_MANIFEST = 'data/shell.json';
const CONTENT_HASH = 'x-plg-content-sha256';
let hashes;
const refreshing = new Map();

async function packHashes() {
  if (!hashes) hashes = (async () => {
    const manifest = await (await caches.open(SHELL_CACHE)).match('data/offline.json');
    const index = await manifest?.json();
    if (!index?.hashes) throw new Error('Offline content hashes are missing from the shell');
    return index.hashes;
  })();
  return hashes;
}

function packPath(request) {
  const url = new URL(typeof request === 'string' ? request : request.url, location.href);
  const base = new URL('./', location.href);
  return url.origin === base.origin && url.pathname.startsWith(base.pathname)
    ? url.pathname.slice(base.pathname.length) : '';
}

async function digest(response) {
  const bytes = await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer());
  return [...new Uint8Array(bytes)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

async function putTagged(cache, request, response, hash) {
  const headers = new Headers(response.headers);
  headers.set(CONTENT_HASH, hash);
  const tagged = new Response(await response.arrayBuffer(), {
    status: response.status, statusText: response.statusText, headers,
  });
  const keys = await cache.keys(request, { ignoreSearch: true });
  await Promise.all((keys.length ? keys : [request]).map((key) => cache.put(key, tagged.clone())));
  return tagged;
}

async function refreshPack(cache, request, expected) {
  const url = new URL(typeof request === 'string' ? request : request.url, location.href);
  url.search = '';
  const key = url.href;
  let work = refreshing.get(key);
  if (!work) {
    work = (async () => {
      const response = await fetch(request, { cache: 'reload' });
      if (!response.ok) return response;
      if (expected) {
        const actual = await digest(response);
        if (actual !== expected) {
          // The CDN can serve this file and the manifest from different deploys for its
          // ten-minute max-age: never store such bytes, but a reader with no copy may
          // still use them.
          throw Object.assign(new Error(`Content hash mismatch: ${key}`), { response });
        }
        return putTagged(cache, request, response, actual);
      }
      await cache.put(request, response.clone());
      return response;
    })();
    refreshing.set(key, work);
  }
  try { return (await work).clone(); }
  finally { if (refreshing.get(key) === work) refreshing.delete(key); }
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL_CACHE);
    const response = await fetch(SHELL_MANIFEST, { cache: 'reload' });
    const files = ['./', SHELL_MANIFEST, ...(await response.json()).files];
    // **A partial shell must not become the active one.** This used to cache what it
    // could and warn about the rest, on the reasoning that failing the install
    // "would leave no service worker at all". That reasoning is backwards: a
    // rejected install does not activate, so the *previous* worker keeps serving
    // from its own complete cache. Half-installing and then activating is what
    // leaves nothing -- `activate` deletes the old shell, so one failed download
    // during a deploy replaced a working offline copy with a broken one, which is
    // the exact case this app exists for.
    //
    // So the install fails loudly and the reader keeps what they had. The names are
    // still reported, because "the deploy is incomplete" is worth seeing in a console.
    const results = await Promise.allSettled(files.map((url) => cache.add(url)));
    const failed = files.filter((_, i) => results[i].status === 'rejected');
    if (failed.length) {
      console.warn('[plg] shell incomplete, keeping the previous version:', failed);
      // Drop the half-built cache so a later attempt starts clean rather than
      // inheriting whichever files happened to arrive this time.
      await caches.delete(SHELL_CACHE);
      throw new Error(`shell incomplete: ${failed.length} of ${files.length} files`);
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    // **Nothing the shell owns may also sit in the pack cache.** The fetch handler
    // below used to revalidate every `/data/` path into `PACK_CACHE`, and that is
    // 221 of the 278 shell files -- the whole registry, all 66 respell tables, all
    // 48 interface catalogues, the theme. `caches.match` searches caches in
    // creation order, and the pack cache outlives a deploy by design, so that copy
    // shadowed the version-scoped one and a deploy did *not* replace it. It is the
    // exact failure the comment on `PACK_CACHE` says is not survivable: last
    // week's modules against this week's data, or worse, this week's
    // `languages.csv` against last week's `scripts.csv` -- which names a script
    // row that does not exist yet and took the studio down with `Cannot read
    // properties of undefined (reading 'font_stack')`.
    //
    // Stopping it at the source is not enough, because every existing reader is
    // already carrying the duplicates. They are dropped here. Nothing a reader
    // saved is lost: `data/concepts/` and `data/lang/` are not in the shell
    // manifest, so a saved pack's rows and its subset fonts are not touched, and
    // the two font files that *are* in the shell keep their shell copy.
    const shell = await caches.open(SHELL_CACHE);
    const pack = await caches.open(PACK_CACHE);
    const expected = await packHashes();
    const failed = [];
    for (const request of await pack.keys()) {
      if (await shell.match(request, { ignoreSearch: true })) { await pack.delete(request); continue; }
      const path = packPath(request);
      if (!expected[path]) continue;
      const cached = await pack.match(request);
      if (!cached) continue;
      const actual = cached.headers.get(CONTENT_HASH) || await digest(cached);
      // One local hash migrates old, untagged saves without downloading them again.
      if (!cached.headers.has(CONTENT_HASH)) await putTagged(pack, request, cached, actual);
      if (actual === expected[path]) continue;
      try {
        if (!(await refreshPack(pack, request, expected[path])).ok) failed.push(path);
      } catch { failed.push(path); }
    }
    if (failed.length) console.warn('[plg] saved files kept offline; refresh will retry when opened:', failed);
    for (const key of await caches.keys()) {
      // Cache Storage belongs to the origin, so leave every other app's caches alone.
      if (key.startsWith(OURS) && key !== SHELL_CACHE && key !== PACK_CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== location.origin) return;

  event.respondWith((async () => {
    // **The shell answers from its own version, and is never refreshed in place.**
    // Its files agree with each other because they were installed together: a
    // deploy changes `VERSION` and installs a new worker with a new shell, and only
    // a complete one activates. This used to revalidate every shell file into the
    // running worker's cache, which was harmless while the next install succeeded
    // and ruinous when it could not -- a reader whose blocker refused one file kept
    // the old worker for good, and its cache filled up file by file with the new
    // deploy, until the studio ran this week's `studio.js` in last week's
    // `customize.html` and died on a button the page did not have.
    //
    // It is also the only cache a page may come from: HTML has to agree with the
    // modules it loads, and a `customize.html` in the pack cache (an older worker
    // put pages there) once served last month's page under this week's JavaScript.
    const shelled = await (await caches.open(SHELL_CACHE)).match(request, { ignoreSearch: true });
    if (shelled) return shelled;
    // Reuse verified files. A failed upgrade refresh leaves the old hash attached,
    // so this read can retry before returning the old bytes as an offline fallback.
    const pack = await caches.open(PACK_CACHE);
    const cached = request.mode === 'navigate' ? undefined : await pack.match(request, { ignoreSearch: true });
    const languageFile = /\/data\/(?:lang|countries|emphasis|fonts)\//.test(url.pathname);
    if (languageFile) {
      const expected = (await packHashes())[packPath(request)];
      if (cached && (!expected || cached.headers.get(CONTENT_HASH) === expected)) return cached;
      try {
        const response = await refreshPack(pack, request, expected);
        if (response.ok || !cached) return response;
        console.warn('[plg] saved file refresh failed; keeping previous copy:', packPath(request), response.status);
      } catch (error) {
        console.warn('[plg] saved file refresh failed; keeping previous copy:', packPath(request), String(error));
        if (!cached && error.response) return error.response;
      }
      return cached || new Response('Offline and this file was never cached.', { status: 504 });
    }
    const fresh = fetch(request).then(async (response) => {
      if (response.ok && request.mode !== 'navigate') await pack.put(request, response.clone());
      return response;
    }).catch(() => null);

    // Previews and other non-language assets may update behind their cached copy.
    if (cached) return cached;
    const response = await fresh;
    if (response) return response;
    return new Response('Offline and this file was never cached.', {
      status: 504, headers: { 'content-type': 'text/plain' },
    });
  })());
});

// The settings ask for a language's data and fonts explicitly, so a reader chooses
// what to carry rather than downloading every script -- and can let it go again, one
// language's files or every saved file at once, to give the space back. Only the pack
// cache is ever emptied: the shell is what the app runs on.
const reply = (event, data) => (event.ports[0] ?? event.source)?.postMessage(data);
self.addEventListener('message', (event) => {
  const data = event.data;
  if (data?.type !== 'forget-urls') return;
  event.waitUntil((async () => {
    if (data.urls) {
      const cache = await caches.open(PACK_CACHE);
      await Promise.all(data.urls.map((/** @type {string} */ url) => cache.delete(url, { ignoreSearch: true })));
    } else {
      await caches.delete(PACK_CACHE);
    }
    reply(event, { type: 'forget-urls-done' });
  })().catch((error) => reply(event, { type: 'forget-urls-done', error: String(error.message) })));
});

self.addEventListener('message', (event) => {
  const data = event.data;
  if (!data || data.type !== 'cache-urls') return;
  event.waitUntil((async () => {
    const cache = await caches.open(PACK_CACHE);
    const shell = await caches.open(SHELL_CACHE);
    // **Skip what the shell already has.** A pair needs its reader's respelling
    // overrides and the Latin face, and both of those are shell files -- already
    // precached, already offline, and nothing here can make them more so. Copying
    // them puts the same file in both caches, which is the shadowing `activate`
    // exists to remove: the pack cache is not version-scoped and answers first, so
    // the copy would outlive the deploy meant to replace it.
    //
    // They still count toward `total`, because the reader asked for a pair and got
    // one; what is reported is whether the pair is saved, not how many requests it
    // took.
    //
    // **`onlyMissing` is the difference between keeping and refreshing.** `cache.add`
    // always fetches, which is what the Save button wants: a pack saved before a data
    // change gets the new rows by being asked for again. A board warms its own pair
    // every time it opens, and re-fetching sixty files on each open would spend a
    // connection the reader may be paying for on rows already in hand -- so that
    // caller asks for the pair to be *present*, not fresh.
    /** @type {string[]} */ const wanted = [];
    for (const url of data.urls) {
      if (await shell.match(url, { ignoreSearch: true })) continue;
      if (data.onlyMissing && await cache.match(url, { ignoreSearch: true })) continue;
      wanted.push(url);
    }
    const expected = await packHashes();
    const results = await Promise.allSettled(wanted.map(async (u) => {
      const response = await refreshPack(cache, u, expected[packPath(u)]);
      if (!response.ok) throw new Error(`HTTP ${response.status}: ${u}`);
    }));
    const failed = wanted.filter((/** @type {string} */ _, /** @type {number} */ i) => results[i].status === 'rejected');
    reply(event, {
      type: 'cache-urls-done', ok: failed.length === 0, failed, total: data.urls.length,
    });
  })().catch((error) => reply(event, { type: 'cache-urls-done', error: String(error.message) })));
});
